#include <stdio.h>
#include <stdlib.h>
#include <limits.h>
#include <stdbool.h>

static long absolute_long(long v) {
    return v < 0 ? -v : v; // caller ensures v != LLONG_MIN
}

static long gcd_long(long a, long b) {
    while (b != 0) {
        long r = a % b;
        a = b;
        b = r;
    }
    return a;
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    char *end1 = NULL, *end2 = NULL;
    long a = strtol(argv[1], &end1, 10);
    long b = strtol(argv[2], &end2, 10);
    if (*end1 != '\0' || *end2 != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (a == LLONG_MIN || b == LLONG_MIN) {
        puts("OVERFLOW");
        return 0;
    }
    long abs_a = absolute_long(a);
    long abs_b = absolute_long(b);
    if (abs_a > 1000000L || abs_b > 1000000L) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    if (abs_a == 0 && abs_b == 0) {
        puts("gcd=0 lcm=0");
        return 0;
    }
    long g = gcd_long(abs_a, abs_b);
    long l = (abs_a / g) * abs_b; // safe due to range limits
    printf("gcd=%ld lcm=%ld\n", g, l);
    return 0;
}
